create or replace function public.business_set_location_amenity(p_business_id uuid,p_location_id uuid,p_amenity_id uuid,p_action text) returns jsonb language plpgsql security definer set search_path=public as $function$ declare ok boolean; result jsonb; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select exists(select 1 from public.business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and lower(bm.role::text) in ('owner','admin','business_owner')) or exists(select 1 from public.profiles p where p.id=auth.uid() and coalesce(p.is_admin,false)) into ok; if not ok then raise exception 'Business owner/admin permission required'; end if; if not exists(select 1 from public.locations where id=p_location_id and business_id=p_business_id) then raise exception 'Location does not belong to business'; end if; if not exists(select 1 from public.amenities where id=p_amenity_id) then raise exception 'Amenity is not in the approved Kleenest amenity catalog'; end if; if lower(p_action)='add' then insert into public.location_amenities(location_id,amenity_id) values(p_location_id,p_amenity_id) on conflict do nothing; elsif lower(p_action) in ('remove','delete') then delete from public.location_amenities where location_id=p_location_id and amenity_id=p_amenity_id; else raise exception 'Action must be add or remove'; end if; return jsonb_build_object('success',true,'action',lower(p_action),'location_id',p_location_id,'amenity_id',p_amenity_id); end;$function$;
create or replace function public.set_location_amenities(p_location_id uuid,p_amenity_ids uuid[]) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $function$ declare v_business uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select business_id into v_business from public.locations where id=p_location_id; if v_business is null then raise exception 'Location not found'; end if; if not (exists(select 1 from public.business_members bm where bm.business_id=v_business and bm.user_id=auth.uid() and lower(bm.role::text) in ('owner','admin')) or exists(select 1 from public.profiles p where p.id=auth.uid() and coalesce(p.is_admin,false))) then raise exception 'Business admin permission required'; end if; if exists(select 1 from unnest(coalesce(p_amenity_ids,'{}'::uuid[])) a where not exists(select 1 from public.amenities am where am.id=a)) then raise exception 'Invalid amenity'; end if; delete from public.location_amenities where location_id=p_location_id; insert into public.location_amenities(location_id,amenity_id) select p_location_id,a from unnest(coalesce(p_amenity_ids,'{}'::uuid[])) a on conflict do nothing; return jsonb_build_object('location_id',p_location_id,'amenity_ids',coalesce(p_amenity_ids,'{}'::uuid[])); end;$function$;
